cpp.setup:
auto* control = new fluent::layout::ListDetailView(%PARENT%);
control->setCompactThreshold(280);
control->setListPaneWidth(156);
auto* listLayout = new QVBoxLayout(control->listPane());
listLayout->setContentsMargins(12, 10, 12, 10);
listLayout->setSpacing(6);
auto* listTitle = new fluent::textfields::Label(QStringLiteral("Inbox"), control->listPane());
listTitle->setFluentTypography(Typography::FontRole::BodyStrong);
auto* listSub = new fluent::textfields::Label(QStringLiteral("Release checklist"), control->listPane());
listSub->setFluentTypography(Typography::FontRole::Caption);
listSub->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
auto* openBtn = new fluent::basicinput::Button(QStringLiteral("Open detail"), control->listPane());
QObject::connect(openBtn, &fluent::basicinput::Button::clicked, control, &fluent::layout::ListDetailView::showDetail);
listLayout->addWidget(listTitle);
listLayout->addWidget(listSub);
listLayout->addStretch();
listLayout->addWidget(openBtn);
auto* detailLayout = new QVBoxLayout(control->detailPane());
detailLayout->setContentsMargins(12, 10, 12, 10);
detailLayout->setSpacing(6);
auto* detailTitle = new fluent::textfields::Label(QStringLiteral("Release checklist"), control->detailPane());
detailTitle->setFluentTypography(Typography::FontRole::BodyStrong);
auto* detailBody = new fluent::textfields::Label(QStringLiteral("All automated checks passed across Light and Dark themes."), control->detailPane());
detailBody->setFluentTypography(Typography::FontRole::Caption);
detailBody->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
detailBody->setWordWrap(true);
auto* backBtn = new fluent::basicinput::Button(QStringLiteral("Back to list"), control->detailPane());
QObject::connect(backBtn, &fluent::basicinput::Button::clicked, control, &fluent::layout::ListDetailView::showList);
detailLayout->addWidget(detailTitle);
detailLayout->addWidget(detailBody);
detailLayout->addStretch();
detailLayout->addWidget(backBtn);
